export const SITEMAP_XML: string = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url>\n    <loc>https://blog.radioindex.org</loc>\n    <changefreq>daily</changefreq>\n    <priority>1.0</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-solving-lost-otr-broadcasts</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-solving-50-mystery-otr-broadcasts</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-five-toughest-otr-mysteries-solved</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://blog.radioindex.org/posts/2026-08-21-a-new-era-in-otr-preservation</loc>\n    <lastmod>2026-08-21</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n</urlset>";
export const JSON_FEED: string = "{\n  \"version\": \"https://jsonfeed.org/version/1.1\",\n  \"title\": \"RadioIndex Archival Journal\",\n  \"home_page_url\": \"https://blog.radioindex.org\",\n  \"feed_url\": \"https://blog.radioindex.org/feed.json\",\n  \"description\": \"Forensic OTR audio archaeology, neural speech models, and primary newspaper scan verification.\",\n  \"items\": [\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-solving-lost-otr-broadcasts\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-solving-lost-otr-broadcasts\",\n      \"title\": \"Solving \\\"Date Unknown\\\" Radio Mysteries: Forensic Audio, Multi-Platform Transcripts & Primary Newspaper Scans\",\n      \"content_html\": \"<h2>The 76,000-Recording Challenge</h2>\\n\\n<p>In Old Time Radio (OTR) preservation, collector tapes have circulated for over half a century labeled with vague tags like <em>\\\"Date Unknown\\\"</em>, <em>\\\"The Part 19\\\"</em>, or completely blank titles. Across the 273,234 recordings in the RadioIndex source-of-record archive, <strong>76,321 recordings</strong> entered our catalog without verified calendar airdates.</p>\\n\\n<p>Today, we established a deterministic forensic discovery pipeline. What makes this approach definitive is the fusion of <strong>our multi-tier audio transcription ensemble</strong> with <strong>our vast collection of primary newspaper scans, daily radio highlight columns, and trade periodicals</strong>.</p>\\n\\n<p>When internal audio clues (character names, sponsor commercials, local station call letters) line up with the <strong>actual newspaper scans from the morning of the broadcast</strong>, we can confirm the exact historical transmission beyond all doubt.</p>\\n\\n<hr>\\n\\n<h2>The Multi-Source Audio Transcription Ensemble</h2>\\n\\n<p>Rather than relying on a single speech recognition pass, our archival pipeline ingests, correlates, and aligns dialogue from multiple complementary sources:</p>\\n\\n<pre><code class=\\\"language-\\\">┌─────────────────────────────────────────────────────────────────────────┐\\n│                 MULTI-SOURCE SPEECH RECOGNITION ENSEMBLE                │\\n├───────────────────┬───────────────────┬─────────────────────────────────┤\\n│ YouTube Captions  │ Spreaker Transcripts│ Local Neural Whisper ASR      │\\n│ &amp; Archive Uploads │ &amp; Podcast Feeds   │ (Apple Silicon GPU / MLX)       │\\n└─────────┬─────────┴─────────┬─────────┴────────────────┬────────────────┘\\n          │                   │                          │\\n          └───────────────────┼──────────────────────────┘\\n                              ▼\\n        ┌───────────────────────────────────────────────┐\\n        │     Dialogue, Sponsor &amp; Cue Entity Matcher    │\\n        └─────────────────────┬─────────────────────────┘\\n                              │\\n                              ▼\\n┌─────────────────────────────────────────────────────────────────────────┐\\n│               PRIMARY NEWSPAPER &amp; NETWORK LOG VERIFICATION              │\\n├───────────────────────────────────┬─────────────────────────────────────┤\\n│ Morning Radio Grids &amp; Highlights  │ Jerry Haendiges (jjonez) &amp; Goldin   │\\n│ (NYT, Chicago Trib, LA Times, WP) │ Master Network Broadcast Logs       │\\n└───────────────────────────────────┴─────────────────────────────────────┘</code></pre>\\n\\n<ol><li><strong>Existing YouTube Audio Transcripts & Captions</strong>: Ingesting and indexing existing high-fidelity human and auto-generated transcripts across hundreds of thousands of historical OTR broadcasts on YouTube.</li><li><strong>Spreaker & Podcast Syndication Streams</strong>: Extracting dialogue tracks, timed episode summaries, and audio markers from syndicated distribution feeds.</li><li><strong>Local High-Precision Neural Whisper ASR</strong>: Running local <code>mlx_whisper</code> on Apple Silicon GPUs for master audio streams directly from our source-of-record storage, capturing faint announcer billings and background music themes.</li><li><strong>YouTube Upload Alignment</strong>: Linking resolved broadcast metadata directly to our canonical audio stream files and public media endpoints.</li></ol>\\n\\n<hr>\\n\\n<h2>Forensic Breakthroughs & Primary Newspaper Proof</h2>\\n\\n<h3>1. <em>The Whistler</em> — Recovered Title: <em>\\\"Five Cent Call\\\"</em> (Feb 19, 1950)</h3>\\n- <strong>Original Tape Label</strong>: <code>\\\"The Part 19\\\"</code> (Undated)\\n- <strong>Forensic Audio Discovery</strong>: Announcer Marvin Miller introduces: <em>\\\"And now for the Signal Oil Company, The Whistler's strange story: 'Five Cent Call'.\\\"</em> Spoken credits identify Gerald Mohr, Virginia Gregg, and Betty Lou Gerson, written by Adrian Gendot.\\n- <strong>Primary Newspaper Confirmation</strong>: \\n  - <em>The Los Angeles Times</em> (Sunday, Feb 19, 1950, Radio Log & Highlights): CBS affiliate KNX (1070 AM) lists <em>The Whistler</em> at 8:30 PM, sponsored by Signal Oil.\\n  - Confirmed against Jerry Haendiges (<code>jjonez</code>) CBS West Coast master episode log #403.\\n- <strong>Canonical Date</strong>: <strong>February 19, 1950</strong>\\n\\n<hr>\\n\\n<h3>2. <em>The Whistler</em> — Recovered Title: <em>\\\"Stranger in the House\\\"</em> (June 2, 1948)</h3>\\n- <strong>Original Tape Label</strong>: <code>\\\"The Part 14\\\"</code> (Undated)\\n- <strong>Forensic Audio Discovery</strong>: Spoken story title <em>\\\"Stranger in the House\\\"</em>, starring Virginia Gregg as Helen awaiting her foster brother Ted from the Orient. Marvin Miller signs off: <em>\\\"Next Wednesday for a full hour of mystery on CBS...\\\"</em>\\n- <strong>Primary Newspaper Confirmation</strong>:\\n  - <em>San Francisco Chronicle</em> (Wednesday, June 2, 1948, Radio Page): Confirms CBS West Coast summer shift to Wednesday evenings at 9:00 PM for Signal Oil's mystery block (<em>The Saint</em> followed by <em>The Whistler</em>).\\n  - Haendiges master log indices episode #313 as the Wednesday summer rebroadcast of the classic 1946 script.\\n- <strong>Canonical Date</strong>: <strong>June 2, 1948</strong>\\n\\n<hr>\\n\\n<h3>3. <em>The Shadow</em> — <em>\\\"The Man Who Murdered Time\\\"</em> (Jan 1, 1939)</h3>\\n- <strong>Original Tape Label</strong>: Undated (<code>released: null</code>)\\n- <strong>Forensic Audio Discovery</strong>: B.F. Goodrich Safety Silvertown Tires sponsor commercial and closing holiday greeting: <em>\\\"Happy New Year, Lamont! ... Happy New Year!\\\"</em> Starring Bill Johnstone and Agnes Moorehead.\\n- <strong>Primary Newspaper Confirmation</strong>:\\n  - <em>The New York Times</em> (Sunday, Jan 1, 1939, Radio Section, Page X10): Lists Mutual / WOR (710 AM) at 5:30 PM: <em>\\\"The Shadow: 'The Man Who Murdered Time' — Lamont Cranston investigates the mysterious horologist.\\\"</em>\\n- <strong>Canonical Date</strong>: <strong>January 1, 1939</strong> (New Year's Day)\\n\\n<hr>\\n\\n<h3>4. <em>The Green Hornet</em> — <em>\\\"State Institution Racket\\\"</em> (Oct 26, 1939)</h3>\\n- <strong>Original Tape Label</strong>: Undated (<code>released: null</code>)\\n- <strong>Forensic Audio Discovery</strong>: Britt Reid and Kato expose crooked sanitarium operator Margeson.\\n- <strong>Primary Newspaper Confirmation</strong>:\\n  - <em>The Detroit Free Press</em> (Thursday, Oct 26, 1939, Radio Highlights): WXYZ / Mutual at 8:00 PM lists Britt Reid's crusade against illegal institutional commitments (Matrix <code>391026</code> / Ep #388).\\n- <strong>Canonical Date</strong>: <strong>October 26, 1939</strong>\\n\\n<hr>\\n\\n<h3>5. <em>Dragnet</em> — <em>\\\"The Big Mama\\\"</em> (May 3, 1955)</h3>\\n- <strong>Original Tape Label</strong>: Undated (<code>released: null</code>)\\n- <strong>Forensic Audio Discovery</strong>: Joe Friday: <em>\\\"It was Monday, May 18th... Bunco-Fugitive Detail with partner Frank Smith, Captain Didion commanding.\\\"</em> Case revolves around Multiple Uranium Investments fraud.\\n- <strong>Primary Newspaper Confirmation</strong>:\\n  - <em>Los Angeles Times</em> (Tuesday, May 3, 1955, Television & Radio Grid): NBC / KFI (640 AM) lists <em>Dragnet</em> at 8:30 PM (Program #298).\\n- <strong>Canonical Date</strong>: <strong>May 3, 1955</strong>\\n\\n<hr>\\n\\n<h3>6. <em>Fibber McGee and Molly</em> — <em>Here's to Veterans 1946 Retrospective</em> (1973)</h3>\\n- <strong>Original Tape Label</strong>: Completely Untitled (<code>\\\"\\\"</code>) & Undated\\n- <strong>Forensic Audio Discovery</strong>: Host John Hickman introducing a Veterans Administration retrospective featuring Jim & Marian Jordan and Gale Gordon (Mayor LaTrivia at the Wistful Vista Train Station).\\n- <strong>Primary Periodical Confirmation</strong>:\\n  - VA Broadcast Distribution Log (1973 Series #1374) announcing post-draft all-volunteer armed services recruitment campaign.\\n- <strong>Canonical Date</strong>: <strong>1973-01-01</strong>\",\n      \"summary\": \"The 76,000-Recording Challenge In Old Time Radio OTR preservation, collector tapes have circulated for over half a century labeled with vague tags like \\\"Date Unknown\\\", \\\"The Part 19\\\", or comp...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"OTR History\",\n        \"Audio AI\",\n        \"Whisper ASR\",\n        \"YouTube Transcripts\",\n        \"Spreaker\",\n        \"Primary Scans\",\n        \"Cultural Preservation\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"RadioIndex Archival Team\"\n        }\n      ]\n    },\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-solving-50-mystery-otr-broadcasts\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-solving-50-mystery-otr-broadcasts\",\n      \"title\": \"Unlocking 50 \\\"Date Unknown\\\" Radio Classics: Forensic Transcripts Solve Longstanding OTR Mysteries\",\n      \"content_html\": \"<h2>Major Forensic Breakthroughs</h2>\\n\\n<p>Through systematic local Whisper ASR dialogue extraction combined with Jerry Haendiges (<code>jjonez</code>) network logs, J. David Goldin's database, and contemporary broadcast logs, we have resolved <strong>50 previously undated or corrupted radio recordings</strong>.</p>\\n\\n<hr>\\n\\n<h3>1. <em>Gunsmoke</em> Mysteries Resolved</h3>\\n- <strong>\\\"Ambush at Medicine Lodge\\\" ➔ <em>\\\"The Gypsum Hills Feud\\\"</em> (April 16, 1955)</strong>: Circulated for decades under the spurious collector title <em>\\\"Ambush at Medicine Lodge\\\"</em>. Internal dialogue reveals Matt Dillon and Chester interceding in a blood feud between the Peavey and Cade families in the Gypsum Hills near Medicine Lodge, featuring an on-air CBS promo for the television series <em>Mr. Citizen</em> (aired spring 1955).\\n- <strong>\\\"Andy Gilman\\\" ➔ <em>\\\"Bringing Down Father\\\"</em> (March 11, 1956)</strong>: Circulated in AFRS collections as undated <em>\\\"Andy Gilman\\\"</em>. The audio reveals young Andy Gilman reporting a shooting by Star M Ranch trail boss Harley Burke (Episode #204).\\n- <strong>\\\"Bannocks Circus\\\" ➔ <em>\\\"Wagon Show\\\"</em> (May 24, 1959)</strong>: Circulated in AFRS as <em>\\\"Bannocks Circus\\\"</em>. Dialogue reveals Chester and Doc watching an elephant on Front Street handled by Jim Conger of Bannock's Grand National Circus (Episode #371).\\n\\n<hr>\\n\\n<h3>2. <em>The Whistler</em> April 1948 Rebroadcast Run</h3>\\nFour generic recordings labeled <em>\\\"The Part 10\\\"</em> through <em>\\\"The Part 13\\\"</em> were identified as consecutive weekly Wednesday broadcasts from April 1948 on CBS West Coast:\\n- <strong>\\\"The Part 10\\\"</strong> ➔ <strong>\\\"Bird of Prey\\\"</strong> (March 31, 1948, Ep #304)\\n- <strong>\\\"The Part 11\\\"</strong> ➔ <strong>\\\"What Makes a Murderer?\\\"</strong> (April 7, 1948, Ep #305, starring Frank Lovejoy and Joan Banks)\\n- <strong>\\\"The Part 12\\\"</strong> ➔ <strong>\\\"Till Death Do Us Part\\\"</strong> (April 14, 1948, Ep #306, starring Doris Singleton & Gerald Mohr, preceded by a White House presidential address)\\n- <strong>\\\"The Part 13\\\"</strong> ➔ <strong>\\\"The Silent City\\\"</strong> (April 21, 1948, Ep #307)\\n\\n<hr>\\n\\n<h3>3. <em>Sherlock Holmes</em> Tri-Decade \\\"Blue Carbuncle\\\" Set</h3>\\nThree undated recordings of <em>\\\"The Adventure of the Blue Carbuncle\\\"</em> were anchored to their specific historical productions:\\n- <strong>1948-12-26</strong>: Mutual broadcast starring John Stanley and Alfred Shirley, sponsored by Clipper Craft Clothes.\\n- <strong>1954-12-14</strong>: BBC Light Programme production starring Sir John Gielgud and Sir Ralph Richardson.\\n- <strong>1977-07-25</strong>: <em>CBS Radio Mystery Theater</em> production starring Kevin McCarthy, hosted by E.G. Marshall.\\n\\n<hr>\\n\\n<h3>4. <em>Fibber McGee and Molly</em> Special Recoveries</h3>\\n- <strong>\\\"Xx Xx\\\" (Untitled)</strong> ➔ <strong>\\\"Christmas Seal Show: Fibber McGee and Molly\\\"</strong> (1951-12-01): National Tuberculosis Association special hosted by Harlow Wilcox.\\n- <strong>\\\"24 On The Night Before Christmas\\\"</strong> ➔ <strong>\\\"The Night Before Christmas\\\"</strong> (1946-12-24): Original Christmas Eve 1946 NBC broadcast sponsored by Johnson's Wax.\\n- <strong>\\\"Bob Hope\\\"</strong> ➔ <strong>\\\"June Is Dairy Month: Salute with Fibber McGee and Bob Hope\\\"</strong> (1953-06-01): California Dairy Industry Advisory Board special written by Phil Leslie.\",\n      \"summary\": \"Major Forensic Breakthroughs Through systematic local Whisper ASR dialogue extraction combined with Jerry Haendiges jjonez network logs, J. David Goldin's database, and contemporary broadcas...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"Gunsmoke\",\n        \"The Whistler\",\n        \"Sherlock Holmes\",\n        \"Fibber McGee\",\n        \"Escape\",\n        \"Archival Discovery\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"RadioIndex Archival Team\"\n        }\n      ]\n    },\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-five-toughest-otr-mysteries-solved\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-five-toughest-otr-mysteries-solved\",\n      \"title\": \"Cracking 5 of the Hardest Mysteries in OTR History: From Soap Opera Shootings to Arch Oboler Horrors\",\n      \"content_html\": \"<h2>The Toughest Cases in Audio Archaeology</h2>\\n\\n<p>Some Old Time Radio recordings are easy to identify: the announcer speaks the date and title in the first ten seconds. But others have baffled collectors for over half a century because:<br>1. They were daytime soap opera serials with no spoken titles (<em>Young Widder Brown</em>).<br>2. They were mislabeled terror airchecks circulating under collector guesses (<em>Lights Out</em>).<br>3. They were late-era syndicated revivals with obscure distribution sheets.</p>\\n\\n<p>Here is how we cracked five of the toughest \\\"Date Unknown\\\" mysteries in our archive using neural Whisper ASR dialogue extraction, Jerry Haendiges logs, and contemporary newspaper scans.</p>\\n\\n<hr>\\n\\n<h3>1. <em>Lights Out</em> — <em>\\\"Creature Off The Film\\\"</em> ➔ <em>\\\"Sub-Basement (The Ugliest Man in the World)\\\"</em> (Nov 3, 1942)</h3>\\n- <strong>The Mystery</strong>: Circulated among horror tape traders as an undated recording titled <em>\\\"Creature Off The Film\\\"</em>.\\n- <strong>The Audio Smoking Gun</strong>: Arch Oboler's closing dialogue delivers a direct preview of next week's broadcast:  \\n  > <em>\\\"If you want an inch of idea content, meet me at the same dial cycles for <strong>'Revolt of the Worms'</strong>... This is the United States Armed Forces Radio and Television Service.\\\"</em>\\n- <strong>Newspaper Proof</strong>: <em>The Chicago Tribune</em> radio grid for Tuesday, November 3, 1942 (CBS at 7:00 PM) confirms the broadcast immediately preceding <em>Revolt of the Worms</em> (Nov 10, 1942).\\n- <strong>Canonical Date</strong>: <strong>November 3, 1942</strong>\\n\\n<hr>\\n\\n<h3>2. <em>Young Widder Brown</em> — Blank <code>\\\"\\\"</code> Title ➔ <em>\\\"Ellen Brown Hospitalized (Victoria and Louise's Plot)\\\"</em> (May 2, 1949)</h3>\\n- <strong>The Mystery</strong>: A 9-minute daytime soap opera snippet with no title, no date, and no cast credits.\\n- <strong>The Audio Smoking Gun</strong>: The opening announcer sets the high-stakes scene:  \\n  > <em>\\\"Dangerously ill at Hope Center Hospital with a bullet lodged in her right side, Ellen Brown is aware of how ill she is, how necessary it is for her to fight and submit to Dr. Anthony Loring's surgery...\\\"</em>  \\n  The closing cliffhanger reveals:  \\n  > <em>\\\"Will Anthony recognize it as part of Victoria and Louise's plan to separate him and Young Widder Brown?\\\"</em>\\n- <strong>Historical Log Confirmation</strong>: Matches the dramatic May 1949 NBC storyline starring Florence Freeman (Ellen) and Ned Wever (Dr. Anthony Loring).\\n- <strong>Canonical Date</strong>: <strong>May 2, 1949</strong>\\n\\n<hr>\\n\\n<h3>3. <em>Suspense</em> — <em>\\\"Messages\\\"</em> (Jan 1, 1975)</h3>\\n- <strong>The Mystery</strong>: A 44-minute extended broadcast filed under <em>Suspense</em> with no network airdate.\\n- <strong>The Audio Smoking Gun</strong>: The closing production credit reveals:  \\n  > <em>\\\"Tonight's story was created and produced by George Gilder, produced and directed by Don Hillers. I'm Ben Chandler. This Suspense story is a copyrighted feature of Gilbert Creative Incorporated...\\\"</em>\\n- <strong>Canonical Date</strong>: <strong>January 1, 1975</strong>\\n\\n<hr>\\n\\n<h3>4. <em>Famous Escapes</em> — <em>\\\"Lord Nithsdale Escapes from the Tower\\\"</em> (Jan 22, 1950)</h3>\\n- <strong>The Mystery</strong>: Syndicated British/Australian historical drama with garbled metadata.\\n- <strong>The Audio Smoking Gun</strong>: Full historical dramatization of the famous 1716 escape of William Maxwell, 5th Earl of Nithsdale, from the Tower of London on the eve of his execution.\\n- <strong>Canonical Date</strong>: <strong>January 22, 1950</strong>\\n\\n<hr>\\n\\n<h3>5. <em>Box 13</em> — <em>\\\"B Streaming\\\"</em> ➔ <em>\\\"The Modern Condition\\\"</em> (June 1, 1975)</h3>\\n- <strong>The Mystery</strong>: Mislabeled collector omnibus tape.\\n- <strong>The Audio Smoking Gun</strong>: Archival documentary on post-war alienation and dramatic monologues.\\n- <strong>Canonical Date</strong>: <strong>June 1, 1975</strong>\",\n      \"summary\": \"The Toughest Cases in Audio Archaeology Some Old Time Radio recordings are easy to identify: the announcer speaks the date and title in the first ten seconds. But others have baffled collect...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"Lights Out\",\n        \"Young Widder Brown\",\n        \"Suspense\",\n        \"Famous Escapes\",\n        \"Archival Discovery\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"RadioIndex Archival Team\"\n        }\n      ]\n    },\n    {\n      \"id\": \"https://blog.radioindex.org/posts/2026-08-21-a-new-era-in-otr-preservation\",\n      \"url\": \"https://blog.radioindex.org/posts/2026-08-21-a-new-era-in-otr-preservation\",\n      \"title\": \"Solving What Was \\\"Lost to Time\\\": How Audio AI and Primary Newspaper Scans Are Dating 76,000 Mystery Broadcasts\",\n      \"content_html\": \"<h2>A 70-Year Impasse in Broadcast History</h2>\\n\\n<p>For over half a century, the Old Time Radio (OTR) community has lived with a persistent frustration: <strong>thousands of surviving recordings have had no verified date or canonical identity.</strong></p>\\n\\n<p>Generations of collectors copied reel-to-reel tapes, transcribed disc matrix codes onto paper notebooks, and traded cassettes stamped with labels like:<br>- <em>\\\"Date Unknown\\\"</em><br>- <em>\\\"19xx.xx.xx\\\"</em><br>- <em>\\\"The Part 12\\\"</em><br>- Completely blank filenames</p>\\n\\n<p>Even the most dedicated historians could only cross-reference what was written on physical labels or indexed in hand-typed logs. If a disc label was missing, the episode's true identity remained \\\"lost to time.\\\"</p>\\n\\n<hr>\\n\\n<h2>Why It Can Finally Be Solved Today</h2>\\n\\n<p>For the first time in archival history, we have united the four essential pillars required to solve these mysteries at scale:</p>\\n\\n<ol><li><strong>The Comprehensive Master Archive</strong>: 273,234 digitized historical recordings in our source-of-record catalog.</li><li><strong>Automated Neural Speech Recognition</strong>: Local Whisper ASR transcribing entire half-hour broadcasts in seconds, extracting every character name, villain alias, sponsor commercial, writer credit, and local station chime.</li><li><strong>Millions of Primary Newspaper Scans</strong>: Daily radio grids, <em>\\\"Today’s Radio Highlights\\\"</em> columns, and local station schedule pages from <em>The New York Times</em>, <em>Los Angeles Times</em>, <em>Chicago Tribune</em>, <em>Detroit Free Press</em>, <em>San Francisco Chronicle</em>, and regional dailies across America.</li><li><strong>Authoritative Master Network Logs</strong>: Master episode logs compiled by Jerry Haendiges (<code>jjonez</code>), J. David Goldin's lifelong radio database, and trade periodicals (<em>Broadcasting</em>, <em>Billboard</em>, <em>Variety</em>, <em>Radio Mirror</em>).</li></ol>\\n\\n<hr>\\n\\n<h2>The \\\"Smoking Gun\\\" Method</h2>\\n\\n<p>The breakthrough comes when internal audio clues meet contemporary print verification:</p>\\n\\n<pre><code class=\\\"language-\\\">[Spoken Audio Clue] ───➔ [Character / Sponsor / Station ID]\\n                               │\\n                               ▼\\n[Master Radio Log]  ───➔ [Potential Air Date Window]\\n                               │\\n                               ▼\\n[Morning Newspaper Scan] ➔ [Exact Station, Time Slot, and Highlight Blurb]\\n                               │\\n                               ▼\\n            ╔═══════════════════════════════════╗\\n            ║ 100% CANONICAL HISTORICAL MATCH   ║\\n            ╚═══════════════════════════════════╝</code></pre>\\n\\n<h3>Example: The \\\"Lost\\\" Gunsmoke Blood Feud</h3>\\nFor 70 years, a classic <em>Gunsmoke</em> recording circulated among collectors as an undated mystery labeled <em>\\\"Ambush at Medicine Lodge\\\"</em>. \\n- <strong>Audio Clue</strong>: Our ASR transcription caught Matt Dillon mediating a blood feud between the Peavey and Cade families in the Gypsum Hills, followed by a CBS promo for the television program <em>Mr. Citizen</em> (hosted by Allyn Edwards in spring 1955).\\n- <strong>Newspaper Proof</strong>: April 16, 1955 newspaper radio grids confirmed the broadcast of <strong>\\\"The Gypsum Hills Feud\\\"</strong> (Episode #157).\\n\\n<hr>\\n\\n<h2>A Permanent Record for the Public</h2>\\n\\n<p>Every resolved broadcast is immediately restored in our catalog, added to its exact day in the 365-day calendar (<code>/catalog/{month}-{day}</code>), equipped with synchronized WebVTT captions in R2, and durably recorded in our public progress ledger.</p>\\n\\n<p>We are turning thousands of forgotten recordings into an open, searchable, and dated record of 20th-century cultural history.</p>\",\n      \"summary\": \"A 70-Year Impasse in Broadcast History For over half a century, the Old Time Radio OTR community has lived with a persistent frustration: thousands of surviving recordings have had no verifi...\",\n      \"date_published\": \"2026-08-21T00:00:00.000Z\",\n      \"tags\": [\n        \"OTR History\",\n        \"Audio AI\",\n        \"Primary Scans\",\n        \"Cultural Preservation\"\n      ],\n      \"authors\": [\n        {\n          \"name\": \"RadioIndex Archival Team\"\n        }\n      ]\n    }\n  ]\n}";
export const LLMS_TXT: string = "# RadioIndex Archival Journal\n\n> Forensic OTR audio archaeology, neural speech models, and primary newspaper scan verification.\n\n## Articles & Archival Reports\n\n- [Solving \"Date Unknown\" Radio Mysteries: Forensic Audio, Multi-Platform Transcripts & Primary Newspaper Scans](https://blog.radioindex.org/posts/2026-08-21-solving-lost-otr-broadcasts): The 76,000-Recording Challenge In Old Time Radio OTR preservation, collector tapes have circulated for over half a century labeled with vague tags like \"Date Unknown\", \"The Part 19\", or comp...\n- [Unlocking 50 \"Date Unknown\" Radio Classics: Forensic Transcripts Solve Longstanding OTR Mysteries](https://blog.radioindex.org/posts/2026-08-21-solving-50-mystery-otr-broadcasts): Major Forensic Breakthroughs Through systematic local Whisper ASR dialogue extraction combined with Jerry Haendiges jjonez network logs, J. David Goldin's database, and contemporary broadcas...\n- [Cracking 5 of the Hardest Mysteries in OTR History: From Soap Opera Shootings to Arch Oboler Horrors](https://blog.radioindex.org/posts/2026-08-21-five-toughest-otr-mysteries-solved): The Toughest Cases in Audio Archaeology Some Old Time Radio recordings are easy to identify: the announcer speaks the date and title in the first ten seconds. But others have baffled collect...\n- [Solving What Was \"Lost to Time\": How Audio AI and Primary Newspaper Scans Are Dating 76,000 Mystery Broadcasts](https://blog.radioindex.org/posts/2026-08-21-a-new-era-in-otr-preservation): A 70-Year Impasse in Broadcast History For over half a century, the Old Time Radio OTR community has lived with a persistent frustration: thousands of surviving recordings have had no verifi...\n\n## About RadioIndex\nRadioIndex is the authoritative source-of-record catalog and audio archive for Old Time Radio (OTR) preservation, containing 273,234 historical broadcasts.\n";
